from fechas import display_date
"""Vista de impresión de requisiciones para BIXOLON: rollo de 80 mm, contenido de 72 mm."""
import html
from app_info import TITLE,VERSION,SUPPORT_LINE

def print_ticket(document):
 e=lambda value:html.escape(str(value),quote=True)
 rows=[]
 for index,line in enumerate(document['partidas'],1):
  note='<p class="line-note">'+e(line['observaciones'])+'</p>' if line['observaciones'] else ''
  delivered='<p class="amount"><span>Cantidad surtida</span><strong>'+e(line['cantidadSurtida'])+' '+e(line['unidad'])+'</strong></p>' if 'cantidadSurtida' in line else ''
  rows.append('<section class="item"><div class="item-heading"><span>'+str(index)+'.</span><strong>'+e(line['nombre'])+'</strong></div><p class="sku">'+e(line['sku'] or 'SIN SKU / ID '+str(line['materialId']))+'</p><p class="amount"><span>Cantidad solicitada</span><strong>'+e(line['cantidad'])+' '+e(line['unidad'])+'</strong></p>'+delivered+note+'</section>')
 info=''.join('<div class="meta-row"><b>'+label+'</b><span>'+e(value)+'</span></div>' for label,value in [('Sucursal',document['sucursal']),('Área',document['area']),('Solicitante',document['solicitante']),('Fecha',display_date(document['fechaHora'])),('Capturó',document.get('nombreUsuario') or document['creadoPor'])])
 general='<section class="general-note"><b>Observaciones</b><p>'+e(document['observaciones'])+'</p></section>' if document['observaciones'] else ''
 signatures=''.join('<div class="signature"><div class="signature-line"></div><span>'+label+' · Nombre y firma</span></div>' for label in ('Solicita','Entrega','Recibe'))
 return ('''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'''+e(document['numero'])+''' · Ticket Bixolon</title><style>
*{box-sizing:border-box}html{background:#f2f3f5}body{margin:0;padding:12px;font:12px Arial,Helvetica,sans-serif;color:#000;display:flex;flex-direction:column;align-items:center}.toolbar{width:min(100%,440px);margin:0 auto 14px;padding:16px;background:white;border:1px solid #ddd;border-radius:10px}.toolbar h1{font-size:17px;margin:0 0 8px}.toolbar p{font-size:12px;line-height:1.5;margin:8px 0}.toolbar button{border:0;border-radius:7px;padding:12px 18px;background:#714b67;color:white;font:600 13px Arial;cursor:pointer;min-height:44px}.toolbar button:disabled{opacity:.5}.ticket{width:80mm;padding:4mm 4mm 6mm;background:white;border:1px solid #ccc;box-shadow:0 3px 12px #0001;overflow-wrap:anywhere}.ticket-header{text-align:center;border-bottom:1px dashed #000;padding-bottom:3mm}.ticket-header img{display:block;width:20mm;height:20mm;object-fit:contain;margin:0 auto 2mm}.ticket-header h2{font-size:13px;line-height:1.35;margin:0 0 2mm}.folio{font-size:16px;font-weight:700;line-height:1.3;margin:2mm 0}.status{font-size:11px;font-weight:700;border:1px solid #000;display:inline-block;padding:1mm 2mm;margin:1mm 0}.meta{margin:3mm 0}.meta-row{margin:0 0 1.5mm;line-height:1.4}.meta-row b{display:block;font-size:10px}.meta-row span{display:block;white-space:pre-wrap}.items{border-top:1px dashed #000}.item{padding:3mm 0;border-bottom:1px dashed #000;break-inside:avoid;page-break-inside:avoid}.item-heading{display:flex;gap:2mm;align-items:flex-start;line-height:1.4}.item-heading span{flex-shrink:0}.item-heading strong{min-width:0;font-size:12px}.sku{font-size:10px;margin:1mm 0 2mm;line-height:1.35}.amount{display:flex;justify-content:space-between;gap:3mm;align-items:flex-start;margin:0;font-size:11px;line-height:1.45}.amount>span{flex:1}.amount strong{max-width:43mm;text-align:right;white-space:pre-wrap}.line-note{margin:2mm 0 0;font-size:11px;white-space:pre-wrap;line-height:1.4}.general-note{padding-top:3mm;line-height:1.4;white-space:pre-wrap;break-inside:avoid}.general-note p{margin:1mm 0 0}.count{margin:3mm 0;font-weight:700;font-size:11px}.signatures{margin-top:6mm;break-inside:avoid;page-break-inside:avoid}.signature{padding-top:8mm;margin-bottom:4mm;text-align:center;font-size:11px}.signature-line{border-bottom:1px solid #000;margin:0 2mm 1.5mm}.app-footer{font-size:8px;line-height:1.4;text-align:center;margin-top:3mm;border-top:1px dashed #000;padding-top:2mm}.app-footer p{margin:1mm 0}.ticket-header,.meta-row,.app-footer{break-inside:avoid}
@media print{html,body{background:white;margin:0;padding:0;display:block}.toolbar{display:none!important}.ticket{border:0;box-shadow:none;margin:0;width:80mm;padding:4mm 4mm 6mm}body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
</style><style id="ticket-page">@page{size:80mm 240mm;margin:0}</style></head><body><aside class="toolbar"><h1>Ticket Bixolon · 80 mm</h1><p>Selecciona tu BIXOLON / <b>bixo</b> en la ventana de impresión. Usa papel de 80 mm, escala al 100 %, sin márgenes ni encabezados y pies del navegador.</p><button type="button" id="ticketPrint">Imprimir / Guardar PDF</button></aside><article class="ticket" id="ticket"><header class="ticket-header"><img src="/logo.png" alt="Grupo Mi Pan"><h2>REQUISICIÓN DE MATERIALES</h2><p class="folio">'''+e(document['numero'])+'''</p><span class="status">'''+e(document['estado'])+'''</span></header><section class="meta">'''+info+'''</section><div class="items">'''+''.join(rows)+'''</div><p class="count">Total de partidas: '''+str(len(document['partidas']))+'''</p>'''+general+'''<footer class="signatures" aria-label="Firmas de la requisición">'''+signatures+'''</footer><div class="app-footer"><p>'''+e(TITLE+' v'+VERSION)+'''</p></div></article><script>
function ticketPageSize(){const mm=Math.ceil(document.getElementById('ticket').getBoundingClientRect().height*25.4/96)+2;document.getElementById('ticket-page').textContent='@page{size:80mm '+Math.min(2000,Math.max(100,mm))+'mm;margin:0}';}
async function ticketReady(){if(document.fonts)await document.fonts.ready;await Promise.all([...document.images].map(img=>img.decode?img.decode().catch(()=>{}):Promise.resolve()));ticketPageSize();}
window.addEventListener('beforeprint',ticketPageSize);window.addEventListener('load',()=>void ticketReady());document.getElementById('ticketPrint').onclick=async()=>{const button=document.getElementById('ticketPrint');button.disabled=true;try{await ticketReady();window.print();}finally{button.disabled=false;}};
</script></body></html>''').encode('utf-8')
